<?php
require __DIR__ . '/layout.php';
require_login();
$where = []; $params = [];
$search = trim((string) ($_GET['q'] ?? ''));
if ($search !== '') { $where[] = '(prospect LIKE ? OR category LIKE ? OR contact_person LIKE ? OR email LIKE ?)'; for ($i=0;$i<4;$i++) $params[] = '%' . $search . '%'; }
foreach (['status' => CRM_STATUSES, 'opportunity_type' => CRM_OPPORTUNITY_TYPES] as $field => $choices) { $value = (string) ($_GET[$field] ?? ''); if (in_array($value, $choices, true)) { $where[] = "$field = ?"; $params[] = $value; } }
$category = trim((string) ($_GET['category'] ?? '')); if ($category !== '') { $where[] = 'category LIKE ?'; $params[] = '%' . $category . '%'; }
$score = trim((string) ($_GET['score'] ?? '')); if ($score !== '' && ctype_digit($score) && (int)$score <= 10) { $where[] = 'score = ?'; $params[] = (int)$score; }
$follow = (string) ($_GET['follow'] ?? ''); if ($follow === 'overdue') $where[] = "follow_up_date < CURDATE() AND status NOT IN ('Closed – Won','Closed – Not Pursuing')"; if ($follow === 'week') { $where[] = "follow_up_date BETWEEN CURDATE() AND DATE_ADD(CURDATE(), INTERVAL 7 DAY)"; }
$sorts = ['follow_up_date' => 'follow_up_date IS NULL, follow_up_date ASC', 'score' => 'score IS NULL, score DESC', 'updated' => 'updated_at DESC', 'prospect' => 'prospect ASC'];
$sort = (string) ($_GET['sort'] ?? 'follow_up_date'); $order = $sorts[$sort] ?? $sorts['follow_up_date'];
$sql = 'SELECT * FROM prospects' . ($where ? ' WHERE ' . implode(' AND ', $where) : '') . ' ORDER BY ' . $order;
$stmt = db()->prepare($sql); $stmt->execute($params); $prospects = $stmt->fetchAll();
page_start('Prospects', 'prospects'); ?>
<div class="page-head"><div><h1>Prospects</h1><p><?= count($prospects) ?> matching prospect<?= count($prospects) === 1 ? '' : 's' ?></p></div><a class="button" href="prospect.php">+ Add prospect</a></div>
<section class="panel"><form class="filters" method="get"><div class="field"><label>Search</label><input name="q" value="<?= e($search) ?>" placeholder="Prospect, person, email…"></div><div class="field"><label>Status</label><select name="status"><option value="">All statuses</option><?php foreach (CRM_STATUSES as $item): ?><option <?= ($_GET['status'] ?? '') === $item ? 'selected' : '' ?>><?= e($item) ?></option><?php endforeach; ?></select></div><div class="field"><label>Opportunity</label><select name="opportunity_type"><option value="">All types</option><?php foreach (CRM_OPPORTUNITY_TYPES as $item): ?><option <?= ($_GET['opportunity_type'] ?? '') === $item ? 'selected' : '' ?>><?= e($item) ?></option><?php endforeach; ?></select></div><div class="field"><label>Category</label><input name="category" value="<?= e($category) ?>" placeholder="e.g. Family venue"></div><div class="field"><label>Score</label><select name="score"><option value="">All scores</option><?php for ($i=10;$i>=0;$i--): ?><option value="<?= $i ?>" <?= $score === (string)$i ? 'selected' : '' ?>><?= $i ?>/10</option><?php endfor; ?></select></div><div class="field"><label>Follow-up</label><select name="follow"><option value="">Any date</option><option value="overdue" <?= $follow === 'overdue' ? 'selected' : '' ?>>Overdue</option><option value="week" <?= $follow === 'week' ? 'selected' : '' ?>>Due this week</option></select></div><div class="field"><label>Sort</label><select name="sort"><option value="follow_up_date" <?= $sort === 'follow_up_date' ? 'selected' : '' ?>>Follow-up date</option><option value="score" <?= $sort === 'score' ? 'selected' : '' ?>>Score</option><option value="updated" <?= $sort === 'updated' ? 'selected' : '' ?>>Recently updated</option><option value="prospect" <?= $sort === 'prospect' ? 'selected' : '' ?>>Name</option></select></div><div class="field"><label>&nbsp;</label><div class="actions"><button class="button" type="submit">Filter</button><a class="button secondary" href="prospects.php">Clear</a></div></div></form></section>
<section class="panel table-wrap"><table><thead><tr><th>Prospect</th><th>Type</th><th>Status</th><th>Score</th><th>Follow-up</th><th>Next step</th></tr></thead><tbody><?php foreach ($prospects as $item): ?><tr><td><a href="<?= e(prospect_url((int)$item['id'])) ?>"><strong><?= e($item['prospect']) ?></strong></a><br><span class="muted"><?= e($item['category']) ?></span></td><td><?= e($item['opportunity_type']) ?></td><td><?= status_badge($item['status']) ?></td><td><?= $item['score'] === null ? '—' : (int)$item['score'] . '/10' ?></td><td><?= e($item['follow_up_date'] ?: '—') ?></td><td><?= e(mb_strimwidth($item['recommended_next_step'] ?: '—', 0, 80, '…')) ?></td></tr><?php endforeach; ?><?php if (!$prospects): ?><tr><td colspan="6" class="empty">No prospects match these filters.</td></tr><?php endif; ?></tbody></table></section>
<?php page_end();
